#include <iostream>
#include <vector>
#include <algorithm>
#include <cstdio>

using namespace std;

struct P {
    int x, y;
    P(int x, int y): x(x), y(y) {}
};

const int INF = 1000000000;

int main() {
    int N, M;

    while (scanf("%d %d", &N, &M), N || M) {
        vector<vector<int>> cost(N, vector<int>(N, INF));
        for (int i = 0; i < N; ++i) cost[i][i] = 0;

        for (int i = 0; i < M; ++i) {
            int a, b, c; 
            scanf("%d %d %d", &a, &b, &c);
            a--, b--;
            cost[a][b] = cost[b][a] = c;
        }

        vector<P> can_free;
        for (int i = 0; i < N; ++i) {
            for (int j = 0; j < N; ++j) {
                if (cost[i][j] != INF && i != j) {
                    for (int k = 0; k < N; ++k) {
                        if (cost[j][k] != INF && i != k && j != k) {
                            can_free.emplace_back(i, k);
                        }
                    }
                }
            }
        }

        for (int k = 0; k < N; ++k) {
            for (int i = 0; i < N; ++i) {
                for (int j = 0; j < N; ++j) {
                    cost[i][j] = min(cost[i][j], cost[i][k] + cost[k][j]);
                }
            }
        }

        int ans = cost[0][N - 1];
        for (const auto& p : can_free) {
            ans = min(cost[0][p.x] + cost[p.y][N - 1], ans);
        }

        printf("%d\n", ans);
    }
}

