        vector<int> cost(N * N, INF);
        for (int i = 0; i < N; ++i) cost[i * N + i] = 0;

        for (int i = 0; i < M; ++i) {
            int a, b, c; 
            scanf("%d %d %d", &a, &b, &c);
            a--, b--;
            cost[a * N + b] = cost[b * N + a] = min(cost[a * N + b], c); // Ensure we take the minimum cost
        }

        vector<P> can_free;
        for (int i = 0; i < N; ++i) {
            for (int j = 0; j < N; ++j) {
                if (cost[i * N + j] != INF && i != j) {
                    for (int k = 0; k < N; ++k) {
                        if (cost[j * N + k] != INF && i != k && j != k) {
                            can_free.emplace_back(i, k);
                        }
                    }
                }
            }
        }

        // Use Floyd-Warshall algorithm to find the shortest paths
        for (int k = 0; k < N; ++k) {
            for (int i = 0; i < N; ++i) {
                if (cost[i * N + k] == INF) continue; // Skip unnecessary checks
                for (int j = 0; j < N; ++j) {
                    if (cost[k * N + j] == INF) continue; // Skip unnecessary checks
                    cost[i * N + j] = min(cost[i * N + j], cost[i * N + k] + cost[k * N + j]);
                }
            }
        }

